import Foundation
import NIO
import NIOConcurrencyHelpers

// MARK: - Multi-tenant Distributed Cache Client

public struct TenantConfig {
    let tenantId: String
    let keyPattern: String
    let maxKeyLength: Int
    let allowedNamespaces: [String]

    public init(tenantId: String, keyPattern: String = "[a-zA-Z0-9_-]+", maxKeyLength: Int = 256, allowedNamespaces: [String] = ["default"]) {
        self.tenantId = tenantId
        self.keyPattern = keyPattern
        self.maxKeyLength = maxKeyLength
        self.allowedNamespaces = allowedNamespaces
    }
}

public enum CacheError: Error {
    case invalidKey(String)
    case tenantNotFound(String)
    case namespaceViolation(String)
    case connectionFailed
    case timeout
    case unsafePattern(String)
}

public final class TenantKeyValidator {
    private var compiledPatterns: [String: NSRegularExpression] = [:]
    private let lock = NIOConcurrencyHelpers.NIOLock()

    // Safe character classes that cannot cause catastrophic backtracking
    private static let safePatternRegex = try! NSRegularExpression(
        pattern: "^(\\[[-a-zA-Z0-9_]+(\\]|\\{\\d+,?\\d*\\})|(\\w|\\d|\\.|[-a-zA-Z0-9_/:])|\\{\\d+,?\\d*\\}|[+?]|\\^|\\$)+$",
        options: []
    )

    // Validates that a cache key conforms to the tenant's configured pattern
    // Uses a two-phase validation: structural check then pattern match
    public func validateKey(_ key: String, for config: TenantConfig) throws -> Bool {
        // Phase 1: Basic structural validation
        guard key.count <= config.maxKeyLength else {
            throw CacheError.invalidKey("Key exceeds maximum length of \(config.maxKeyLength)")
        }

        guard !key.isEmpty else {
            throw CacheError.invalidKey("Key cannot be empty")
        }

        // Phase 2: Pattern-based validation against tenant config
        let pattern = try getOrCompilePattern(for: config)
        let range = NSRange(key.startIndex..<key.endIndex, in: key)

        guard pattern.firstMatch(in: key, options: [.anchored], range: range) != nil else {
            throw CacheError.invalidKey("Key '\(key)' does not match tenant pattern")
        }

        return true
    }

    private func getOrCompilePattern(for config: TenantConfig) throws -> NSRegularExpression {
        lock.lock()
        defer { lock.unlock() }

        if let cached = compiledPatterns[config.tenantId] {
            return cached
        }

        // Build the full validation regex from tenant config
        // Format: namespace:key where key must match the tenant's pattern
        let fullPattern = buildIsolationPattern(config: config)
        let regex = try NSRegularExpression(pattern: fullPattern, options: [])
        compiledPatterns[config.tenantId] = regex
        return regex
    }

    // Constructs a regex that enforces tenant isolation by requiring
    // keys to be prefixed with an allowed namespace
    private func buildIsolationPattern(config: TenantConfig) -> String {
        let namespaceAlternation = config.allowedNamespaces
            .map { NSRegularExpression.escapedPattern(for: $0) }
            .joined(separator: "|")

        // The tenant's keyPattern is used with possessive quantifiers to prevent backtracking
        // This creates: ^(namespace1|namespace2):(<tenantKeyPattern>)$
        let combined = "^(\(namespaceAlternation)):(\(config.keyPattern))$"
        return combined
    }

    /// Checks if a pattern is safe from catastrophic backtracking
    /// Rejects patterns with nested quantifiers or ambiguous alternations
    public static func isPatternSafe(_ pattern: String) -> Bool {
        // Reject patterns with nested quantifiers like (a+)+ or (a|a)*
        // Check for overlapping alternations and nested repetition

        // Rule 1: No nested quantifiers (quantifier applied to group containing quantifier)
        var depth = 0
        var hasQuantifierAtDepth: [Int: Bool] = [:]
        var i = pattern.startIndex
        while i < pattern.endIndex {
            let c = pattern[i]
            if c == "(" {
                depth += 1
                hasQuantifierAtDepth[depth] = false
            } else if c == ")" {
                let nextIdx = pattern.index(after: i)
                if nextIdx < pattern.endIndex {
                    let next = pattern[nextIdx]
                    if next == "*" || next == "+" || next == "?" || next == "{" {
                        // This group has a quantifier
                        if hasQuantifierAtDepth[depth] == true {
                            return false // Nested quantifier detected
                        }
                        if depth > 0 {
                            hasQuantifierAtDepth[depth - 1] = true
                        }
                    }
                }
                hasQuantifierAtDepth.removeValue(forKey: depth)
                depth -= 1
            } else if c == "*" || c == "+" {
                hasQuantifierAtDepth[depth] = true
            }
            i = pattern.index(after: i)
        }

        return true
    }
}

public final class DistributedCacheClient {
    private let validator: TenantKeyValidator
    private var tenantConfigs: [String: TenantConfig] = [:]
    private let configLock = NIOConcurrencyHelpers.NIOLock()

    public init() {
        self.validator = TenantKeyValidator()
    }

    public func registerTenant(_ config: TenantConfig) throws {
        // Validate the pattern is safe before registering
        guard TenantKeyValidator.isPatternSafe(config.keyPattern) else {
            throw CacheError.unsafePattern("Pattern '\(config.keyPattern)' may cause catastrophic backtracking")
        }
        configLock.lock()
        defer { configLock.unlock() }
        tenantConfigs[config.tenantId] = config
    }

    // Primary cache access method with tenant isolation
    public func get(key: String, tenantId: String) throws -> Data? {
        let config = try resolveConfig(tenantId: tenantId)
        let _ = try validator.validateKey(key, for: config)

        // In production, this would call the distributed cache backend
        return performCacheLookup(isolatedKey: "\(tenantId)/\(key)")
    }

    public func set(key: String, value: Data, tenantId: String, ttl: TimeInterval = 3600) throws {
        let config = try resolveConfig(tenantId: tenantId)
        let _ = try validator.validateKey(key, for: config)

        performCacheWrite(isolatedKey: "\(tenantId)/\(key)", value: value, ttl: ttl)
    }

    private func resolveConfig(tenantId: String) throws -> TenantConfig {
        configLock.lock()
        defer { configLock.unlock() }

        guard let config = tenantConfigs[tenantId] else {
            throw CacheError.tenantNotFound(tenantId)
        }
        return config
