// MARK: - Tenant Onboarding Service

public final class TenantOnboardingService {
    private let cacheClient: DistributedCacheClient

    public init(cacheClient: DistributedCacheClient) {
        self.cacheClient = cacheClient
    }

    /// Onboards a tenant with their custom key validation pattern.
    /// Only safe patterns (no nested quantifiers) are accepted.
    /// Allowed patterns:
    ///   - "[a-zA-Z0-9_-]+" for simple alphanumeric keys
    ///   - "[a-z]+/[a-z]+" for single-level path keys
    ///   - "session_[a-f0-9]{32}" for session-specific keys
    public func onboardTenant(
        tenantId: String,
        keyPattern: String,
        namespaces: [String] = ["default", "session", "cache"]
    ) throws {
        // Validate the pattern itself is a valid regex
        let _ = try NSRegularExpression(pattern: keyPattern, options: [])

        let config = TenantConfig(
            tenantId: tenantId,
            keyPattern: keyPattern,
            maxKeyLength: 256,
            allowedNamespaces: namespaces
        )

        // registerTenant will reject unsafe patterns
        try cacheClient.registerTenant(config)
    }
}

// MARK: - Example Usage / Integration Test

func demonstrateUsage() throws {
    let client = DistributedCacheClient()
    let onboarding = TenantOnboardingService(cacheClient: client)

    // Tenant A uses simple alphanumeric keys with slashes
    try onboarding.onboardTenant(
        tenantId: "tenant-a",
        keyPattern: "[a-z/]+"
    )

    // Tenant B uses session keys
    try onboarding.onboardTenant(
        tenantId: "tenant-b",
        keyPattern: "session_[a-f0-9]{32}"
    )

    // Valid access
    let _ = try client.get(key: "default:users/profiles/active", tenantId: "tenant-a")
    let _ = try client.get(key: "session:session_deadbeef01234567890abcdef1234567", tenantId: "tenant-b")
}
